let cap=2400;let sample=data.length<=cap?data:Array.from({length:cap},(_,i)=>data[Math.floor(i*(data.length-1)/(cap-1))]);scatterPoints=sample.map(r=>({r,x:x(xVal(r)),y:y(sqm(r))}));let baseline=ctx.getImageData(0,0,canvas.width,canvas.height);let start=performance.now();if(canvas._frame)cancelAnimationFrame(canvas._frame);function draw(now){let p=duration?Math.min(1,(now-start)/duration):1;ctx.putImageData(baseline,0,0);let n=Math.ceil(scatterPoints.length*p);for(let i=0;i<n;i++){let d=scatterPoints[i];ctx.beginPath();ctx.fillStyle=colors[d.r[2]];ctx.globalAlpha=.53;ctx.arc(d.x,d.y,2.7,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;if(p<1)canvas._frame=requestAnimationFrame(draw)}canvas._frame=requestAnimationFrame(draw);
