let brushing=null;
$('#scatter').addEventListener('pointerdown',e=>{if(!scatterAxes)return;let r=e.currentTarget.getBoundingClientRect(),px=e.clientX-r.left;if(px<scatterAxes.left||px>scatterAxes.right)return;brushing={start:px,px};e.currentTarget.setPointerCapture(e.pointerId);hideTip()});
