$('#scatter').addEventListener('pointerup',()=>{if(!brushing)return;let {start,px}=brushing;brushing=null;$('#brushRect').style.display='none';if(Math.abs(start-px)>8){let a=scatterAxes;let inverse=v=>(v-a.left)/(a.right-a.left)*a.xMax;state.brush=[inverse(Math.min(start,px)),inverse(Math.max(start,px))];render()}});$('#scatter').addEventListener('pointercancel',()=>{brushing=null;$('#brushRect').style.display='none'});$('#scatter').addEventListener('pointerleave',()=>{if(!brushing)hideTip()});
function renderFloors(){let c=chartBase('#boxplot',1100,360);let data=filtered.filter(r=>state.age==='all'||r[10]!==null&&(state.age==='young'?yearOf(r)-r[10]<20:state.age==='middle'?yearOf(r)-r[10]>=20&&yearOf(r)-r[10]<40:yearOf(r)-r[10]>=40));let labels=['1–10','>10–20','>20–30','>30'];let bins=[0,1,2,3].map(b=>{let rs=data.filter(r=>Math.min(3,Math.floor(((r[4]+r[5])/2-.001)/10))===b),a=rs.map(sqm).sort((a,b)=>a-b);return {b,n:a.length,a,med:a.length?quantile(a,.5):NaN}});let vals=bins.flatMap(b=>b.a),max=vals.length?maxOf(vals,v=>v)*1.08:10000;let ax=axes(c,{xMin:-.5,xMax:3.5,yMax:max,xTicks:[0,1,2,3],xFormat:i=>labels[i],yFormat:money,xLabel:'Storey-range midpoint band',yLabel:'SGD / m²',bottom:50});if(!vals.length){empty(c);$('#floorInsight').textContent='No transactions match the selected building-age group.';return}
sync(c.plot,'g',bins.filter(b=>b.n),b=>b.b,(g,b,fresh)=>{if(fresh){g._whisker=el('line',{},g);g._box=el('rect',{},g);g._median=el('line',{},g);g._cap1=el('line',{},g);g._cap2=el('line',{},g);g._count=el('text',{},g)}let X=ax.x(b.b),a=b.a,low=ax.y(quantile(a,.1)),high=ax.y(quantile(a,.9)),q1=ax.y(quantile(a,.25)),q3=ax.y(quantile(a,.75)),mid=ax.y(b.med);for(let n of [g._whisker,g._cap1,g._cap2]){n.setAttribute('stroke','var(--green)');n.setAttribute('stroke-width',1.6)}animateAttrs(g._whisker,{x1:X,x2:X,y1:low,y2:high});animateAttrs(g._cap1,{x1:X-18,x2:X+18,y1:low,y2:low});animateAttrs(g._cap2,{x1:X-18,x2:X+18,y1:high,y2:high});g._box.setAttribute('fill','#bdd0be');g._box.setAttribute('stroke','#6b8d7c');animateAttrs(g._box,{x:X-45,y:q3,width:90,height:q1-q3});g._median.setAttribute('stroke','#bf6b43');g._median.setAttribute('stroke-width',3);animateAttrs(g._median,{x1:X-45,x2:X+45,y1:mid,y2:mid});g._count.setAttribute('x',X);g._count.setAttribute('y',Math.max(20,high-11));g._count.setAttribute('text-anchor','middle');g._count.textContent='n = '+num(b.n);g.onpointermove=e=>showTip(e,'<b>Storey midpoint '+labels[b.b]+'</b>Median '+money(b.med)+' / m²<br>Middle 50%: '+money(quantile(a,.25))+'–'+money(quantile(a,.75))+'<br><small>'+num(b.n)+' sales · 10th–90th percentile whiskers</small>');g.onpointerleave=hideTip});let active=bins.filter(b=>b.n);$('#floorInsight').textContent=active.map(b=>'Storeys '+labels[b.b]+': '+money(b.med)+'/m²').join(' · ')+'. The distributions reflect this filtered housing mix; the differences are not controlled causal floor premiums.'}
function renderHeatmap(){let data=rows.filter(r=>matches(r,{skipTown:true,skipType:true})),map=groups(data,r=>r[1]+':'+r[2]),values=[...map.values()].map(a=>median(a.map(sqm))),min=Math.min(...values),max=Math.max(...values),types=meta.types.map((t,i)=>({t,i})),towns=meta.towns.map((t,i)=>({t,i}));let root=$('#heatmap');root.style.gridTemplateColumns='145px repeat('+types.length+',minmax(65px,1fr))';let html='<div class="heat-label">SGD / m²</div>'+types.map(t=>'<div class="heat-label type-label">'+escape(t.t)+'</div>').join('');for(let town of towns){html+='<div class="heat-label">'+escape(title(town.t))+'</div>';for(let type of types){let a=map.get(town.i+':'+type.i),v=a?median(a.map(sqm)):NaN;let selected=(state.town==='all'||+state.town===town.i)&&(state.type==='all'||+state.type===type.i),opacity=selected?1:.32;html+='<button '+(!a?'disabled':'')+' class="heat-cell '+(!a?'empty':'')+' '+(state.town===String(town.i)&&state.type===String(type.i)?'selected':'')+'" data-town="'+town.i+'" data-type="'+type.i+'" style="'+(a?'background:'+colorValue(v,min,max)+';':'')+'opacity:'+opacity+'" aria-label="'+escape(town.t+' '+type.t+(a?', median '+money(v)+' per square metre, '+a.length+' sales':', no transactions'))+'">'+(a?num(v):'—')+'</button>'}}root.innerHTML=html;$$('.heat-cell:not(:disabled)').forEach(b=>{b.onclick=()=>{state.town=b.dataset.town;state.type=b.dataset.type;render()};b.onpointermove=e=>{let a=map.get(b.dataset.town+':'+b.dataset.type),s=stats(a);showTip(e,'<b>'+escape(title(meta.towns[+b.dataset.town]))+' · '+escape(meta.types[+b.dataset.type])+'</b>'+money(s.sqm)+' / m²<br>'+money(s.price)+' median sale<br><small>'+num(s.n)+' recorded sales</small>')};b.onpointerleave=hideTip})}
