function saveState(){try{let p=new URLSearchParams;for(let k of ['year','town','type'])if(state[k]!=='all')p.set(k,state[k]);history.replaceState(null,'',location.pathname+(p.size?'?'+p:'')+location.hash)}catch{}}
function reset(){Object.assign(state,{year:'all',town:'all',type:'all',age:'all',brush:null});stopPlayback();render()}
function stopPlayback(){clearInterval(playTimer);playTimer=null;$('#play').textContent='▶ Play years'}
function playback(){if(playTimer){stopPlayback();return}state.year='2017';render();$('#play').textContent='Ⅱ Pause';playTimer=setInterval(()=>{if(+state.year>=2026){stopPlayback();return}state.year=String(+state.year+1);render()},reduced?1600:1200)}
function wire(){for(let k of ['year','type','town'])$('#'+k).onchange=e=>{stopPlayback();state[k]=e.target.value;render()};$('#reset').onclick=reset;$('#startOver').onclick=()=>{reset();$('#market').scrollIntoView({behavior:reduced?'instant':'smooth'})};$('#clearTown').onclick=()=>selectTown('all');$('#clearMatrix').onclick=()=>{state.town='all';state.type='all';render()};$('#clearBrush').onclick=()=>{state.brush=null;render()};$('#ageGroup').onchange=e=>{state.age=e.target.value;renderFloors()};$('#play').onclick=playback;$('#timeline').oninput=e=>{stopPlayback();state.year=e.target.value;queueRender()};for(let [id,key]of [['trendMetric','trend'],['scatterMetric','scatter']])$$('#'+id+' button').forEach(b=>b.onclick=()=>{state[key]=b.dataset.value;if(key==='scatter')state.brush=null;$$('#'+id+' button').forEach(n=>n.classList.toggle('active',n===b));render()});$('#controlType').onclick=()=>{state.type=String(meta.types.indexOf('4 ROOM'));render()};$('#controlTown').onclick=()=>{state.type=String(meta.types.indexOf('4 ROOM'));state.town=String(meta.towns.indexOf('TOA PAYOH'));render()};$('#allFlats').onclick=reset;$$('[data-map]').forEach(b=>b.onclick=()=>zoomMap(b.dataset.map,b.dataset.zoom));for(let id of ['showMrt','showHawker'])$('#'+id).onchange=renderAmenities;$('#clearArea').onclick=()=>{state.area='all';renderAmenities()};$('#export').onclick=exportCSV;$('#theme').onclick=()=>{document.body.classList.toggle('dark');let dark=document.body.classList.contains('dark');$('#theme').setAttribute('aria-label','Switch to '+(dark?'light':'dark')+' mode');try{localStorage.setItem('hdb-theme',dark?'dark':'light')}catch{}renderScatter()};for(let id of ['methodBtn','methodFooter'])$('#'+id).onclick=()=>$('#methods').showModal();$('#closeMethods').onclick=()=>$('#methods').close();$('#methods').onclick=e=>{if(e.target===$('#methods')){let r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};$('#present').onclick=enterPresentation;$('#pExit').onclick=exitPresentation;$('#pPrev').onclick=()=>changeChapter(-1);$('#pNext').onclick=()=>changeChapter(1);$('#pAuto').onclick=toggleTour;document.addEventListener('keydown',e=>{if(state.present&&e.target.tagName!=='SELECT'&&e.target.tagName!=='INPUT'&&!$('#methods').open){if(e.key==='ArrowRight')changeChapter(1);if(e.key==='ArrowLeft')changeChapter(-1);if(e.key==='Escape')exitPresentation()}});let resize;addEventListener('resize',()=>{clearTimeout(resize);resize=setTimeout(renderScatter,150)});try{if(localStorage.getItem('hdb-theme')==='dark'){document.body.classList.add('dark');$('#theme').setAttribute('aria-label','Switch to light mode')}}catch{}
let sections=$$('.chapter');let observer=new IntersectionObserver(entries=>{for(let e of entries){if(e.isIntersecting){e.target.classList.add('visible');$$('.chapter-nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+e.target.id))}}},{threshold:.12});sections.forEach(s=>observer.observe(s));}
function exportCSV(){let cols=['month','town','flat_type','block_address','storey_range','floor_area_sqm','flat_model','remaining_lease_years','resale_price','price_per_sqm','year_completed','max_floor_level'];let q=v=>'"'+String(v??'').replace(/"/g,'""')+'"';let csv=cols.join(',')+'\r\n'+filtered.map(r=>[monthLabel(r[0]),meta.towns[r[1]],meta.types[r[2]],meta.blocks[r[3]],r[4]+' TO '+r[5],r[6],meta.models[r[7]],(r[8]/12).toFixed(4),r[9],sqm(r).toFixed(4),r[10],r[11]].map(q).join(',')).join('\r\n');let a=document.createElement('a'),url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='hdb-atlas-filtered-'+(state.year==='all'?'2017-2026':state.year)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function enterPresentation(){stopPlayback();state.present=true;state.chapter=0;tourElapsed=0;document.body.classList.add('presentation');$('#presentationBar').hidden=false;showChapter();updateClock()}
function exitPresentation(){state.present=false;clearInterval(tourTimer);tourTimer=null;$('#pAuto').textContent='▶ Start timed tour';document.body.classList.remove('presentation');$('#presentationBar').hidden=true;$$('.chapter').forEach(s=>s.classList.remove('current'));renderScatter();$('#market').scrollIntoView({behavior:'instant'})}
function showChapter(){let sections=$$('.chapter');sections.forEach((s,i)=>s.classList.toggle('current',i===state.chapter));$('#pTitle').textContent=String(state.chapter+1).padStart(2,'0')+' / '+sections[state.chapter].dataset.title;$('#pPrev').disabled=state.chapter===0;$('#pNext').disabled=state.chapter===5;window.scrollTo({top:0,behavior:'instant'});if(state.chapter===2)renderScatter()}
function changeChapter(d){state.chapter=Math.max(0,Math.min(5,state.chapter+d));if(tourTimer)tourElapsed=state.chapter*60;showChapter();updateClock()}
function updateClock(){let remaining=Math.max(0,360-tourElapsed);$('#pClock').textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0');$('#pProgress').style.width=(tourElapsed/360*100)+'%'}
function toggleTour(){if(tourTimer){clearInterval(tourTimer);tourTimer=null;$('#pAuto').textContent='▶ Resume tour';return}if(tourElapsed>=360){tourElapsed=0;state.chapter=0;showChapter()}$('#pAuto').textContent='Ⅱ Pause tour';tourTimer=setInterval(()=>{tourElapsed++;let chapter=Math.min(5,Math.floor(tourElapsed/60));if(chapter!==state.chapter){state.chapter=chapter;showChapter()}updateClock();if(tourElapsed>=360){clearInterval(tourTimer);tourTimer=null;$('#pAuto').textContent='↺ Replay tour'}},1000)}
function methodology(){$('#methodContent').innerHTML='<p>This webpage uses only the six uploaded datasets. The assignment PDF and Word template inform the presentation layout; they supply no price or location observations.</p><h3>Coverage and joins</h3><p><b>'+num(meta.count)+' resale transactions</b>, '+meta.start+' to '+meta.end+'. The 2026 year is partial. HDB building records are joined on trimmed, uppercase block + street: <b>'+num(meta.matched)+' matched</b>; three MacPherson Lane block 82 records are unmatched. Those sales remain in the price analysis and are excluded from building-age-specific views.</p><h3>Measures</h3><ul><li>Sale price is nominal SGD. Price per m² is calculated for each transaction before taking the median; it is not median price divided by median size.</li><li>Remaining lease converts the recorded years and months to years. Building age equals transaction year minus completion year, not lease commencement year.</li><li>Storey bands use the midpoint of the supplied storey range, with nonoverlapping thresholds 1–10, &gt;10–20, &gt;20–30 and &gt;30. Boxes span the 25th–75th percentiles; whiskers are the 10th–90th percentiles.</li><li>The growth index divides each monthly median by the corresponding 2017 annual median. Types without a 2017 baseline are omitted in index mode. The trend respects town, type and property range; year selection progressively reveals the history through that year.</li><li>KPI, ranking, matrix and distributions use all filtered rows. The scatterplot displays up to 2,400 deterministic, evenly spaced sample rows for clarity. Samples are not used for statistics.</li><li>The location ranking ignores the selected town to retain comparison context. The matrix ignores town and type selections, highlights the selected cell, and respects period and property range. The building-age selector applies only to the floor distribution.</li></ul><h3>Geographic boundaries and limitations</h3><p>55 planning-area geometries are from the uploaded Master Plan file. Price symbols are town groups anchored to directly named planning areas, not choropleth estimates or spatially assigned sales. Central Area and Kallang/Whampoa have no direct planning-area match. Polygon holes and multipolygons are retained.</p><p>613 MRT exit points and 129 hawker points are spatially assigned by point-in-polygon to uploaded boundaries. Hawker records include all supplied statuses. '+meta.schools.length+' primary schools are counted by the school file’s DGP classification, not geocoded; '+meta.allSchoolCount+' schools appear in the complete school file. Exit counts are not station counts. No historical amenity reconstruction is available.</p><p>HDB blocks and schools lack coordinates. No distance bands, walking times, school proximity premiums or causal amenity price effects are fabricated. The illustrated housing scene is decorative and encodes no data.</p><h3>Source files</h3><ul>'+meta.sources.map(s=>'<li>'+escape(s.name)+'<br><code>SHA-256: '+s.sha256+'</code></li>').join('')+'</ul><h3>Presentation</h3><p>The six-minute mode allocates one minute to each chapter, pauses on request, and supports arrow-key navigation. The source assignment requests each student’s own narration. This webpage does not generate narration or export a video.</p>'}
async function init(){try{$('#loadBar').style.width='15%';let responses=await Promise.all([fetch('metadata.json'),fetch('transactions.json')]);if(responses.some(r=>!r.ok))throw Error('Dataset could not be loaded.');meta=await responses[0].json();$('#loadBar').style.width='45%';rows=await responses[1].json();$('#loadBar').style.width='85%';for(let y=2017;y<=2026;y++){let o=document.createElement('option');o.value=y;o.textContent=y===2026?'2026 (Jan–Oct)':y;$('#year').append(o)}for(let k of ['town','type']){for(let [i,t]of meta[k==='town'?'towns':'types'].entries()){let o=document.createElement('option');o.value=i;o.textContent=k==='town'?title(t):t;$('#'+k).append(o)}}let params=new URLSearchParams(location.search);for(let k of ['year','town','type']){let v=params.get(k),valid=k==='year'?v&&+v>=2017&&+v<=2026:v!==null&&/^\d+$/.test(v)&&+v<meta[k==='town'?'towns':'types'].length;if(valid)state[k]=v}wire();methodology();render();$('#loading').hidden=true;$('#loadBar').style.width='100%';setTimeout(()=>$('#loadBar').hidden=true,700);window.HDBAtlas={state,meta,rows,get filtered(){return filtered},render,stats,matches,enterPresentation,exitPresentation,changeChapter,zoomMap};}catch(e){console.error(e);$('#loading').textContent='The data could not be loaded. Serve this folder with a local web server and refresh. '+e.message;$('#loading').setAttribute('role','alert')}}
init();
